export type AudioSubchapter = {
  label: string;    // "A", "B", "C", …
  filename: string; // e.g. "L08Ch002A"
};

export type AudioChapter = {
  number: number;
  // Either a single file (no subchapters) or split into labelled subchapters
  filename?: string;
  subchapters?: AudioSubchapter[];
};

export type AudioVolume = {
  number: number;
  chapters: AudioChapter[];
};

export type Audiobook = {
  id: string;
  title: string;
  author: string;
  description: string;
  cover: ReturnType<typeof require> | null;
  volumes: AudioVolume[];
};

